271→const extractVisiblePrice = (
272→	html: string,
273→	expectedCurrency: CurrencyCode,
274→): ExtractedPriceData | undefined => {
275→	const pricePatterns = CURRENCY_SYMBOLS[expectedCurrency]
276→		.map((symbol) => symbol.replace(/[.*+?^${}()|[\]\\]/gu, "\\$&"))
277→		.map((escaped) => new RegExp(`${escaped}\\s*([\\d,.]+)`, "u"));
278→
279→	for (const pattern of pricePatterns) {
280→		const match = html.match(pattern);
281→		if (!match?.[1]) {
282→			continue;
283→		}
284→
285→		const localPrice = parsePriceNumber(match[1]);
286→		if (localPrice === undefined) {
287→			continue;
288→		}
289→
290→		return {
291→			productName: normalizeProductName(getTagText(html, "h1") ?? getTagText(html, "title")),
292→			sku:
293→				normalizeWhitespace(
294→					html.match(/(?:sku|style|item)\s*(?:#|number|no\.?)?\s*[:#]?\s*([a-z0-9-]+)/iu)?.[1],
295→				) ?? undefined,
296→			localPrice,
297→			currency: expectedCurrency,
298→			available: true,
299→			confidence: "medium",
300→		};
301→	}
302→
303→	if (/(sold out|out of stock|unavailable)/iu.test(html)) {
304→		return {
305→			productName: normalizeProductName(getTagText(html, "h1") ?? getTagText(html, "title")),
306→			available: false,
307→			confidence: "low",
308→		};
309→	}
310→
311→	return undefined;
312→};
