353→export class RuleBasedPriceExtractor implements PriceExtractorApi {
354→	extract(
355→		html: string,
356→		context: PriceExtractionContext,
357→	): Effect.Effect<ExtractedPriceData, ExtractionError> {
358→		return Effect.try({
359→			try: () => {
360→				const structured = extractStructuredData(html, context.expectedCurrency);
361→				const meta = structured ?? extractMetaData(html, context.expectedCurrency);
362→				const visible = meta ?? extractVisiblePrice(html, context.expectedCurrency);
363→
364→				if (!visible) {
365→					throw new ExtractionError({
366→						url: context.url,
367→						reason: "Could not extract product data from page HTML.",
368→					});
369→				}
370→
371→				return visible;
372→			},
373→			catch: (cause) =>
374→				cause instanceof ExtractionError
375→					? cause
376→					: new ExtractionError({
377→							url: context.url,
378→							reason: "Rule-based extraction failed.",
379→							cause,
380→						}),
381→		});
382→	}
383→}
384→
385→export class OpenRouterPriceExtractor implements PriceExtractorApi {
386→	private readonly client: OpenAI;
387→
388→	constructor(
389→		private readonly apiKey: string,
390→		private readonly baseURL = Bun.env.LLM_BASE_URL ?? "https://openrouter.ai/api/v1",
391→		private readonly model = Bun.env.LLM_MODEL ?? "google/gemini-2.0-flash-001",
392→	) {
393→		this.client = new OpenAI({
394→			apiKey,
395→			baseURL,
396→		});
397→	}
398→
399→	extract(
400→		html: string,
401→		context: PriceExtractionContext,
402→	): Effect.Effect<ExtractedPriceData, ExtractionError> {
403→		return Effect.tryPromise({
404→			try: async () => {
405→				const cleanedHtml = cleanHtml(html);
406→				const response = await this.client.chat.completions.create({
407→					model: this.model,
408→					temperature: 0,
409→					response_format: { type: "json_object" },
410→					messages: [
411→						{
412→							role: "system",
413→							content:
414→								"You extract structured product pricing data from ecommerce HTML. Return only JSON.",
415→						},
416→						{
417→							role: "user",
418→							content: [
419→								`Brand: ${context.brand}`,
420→								`Region: ${context.region}`,
421→								`Expected currency: ${context.expectedCurrency}`,
422→								"Return a JSON object with:",
423→								"- productName: string or null",
424→								"- sku: string or null",
425→								"- localPrice: number or null",
426→								"- currency: ISO 4217 currency code or null",
427→								"- available: boolean",
428→								'- confidence: "high" | "medium" | "low"',
429→								"",
430→								cleanedHtml,
431→							].join("\n"),
432→						},
433→					],
434→				});
435→				const content = response.choices[0]?.message?.content;
436→				if (!content) {
437→					throw new ExtractionError({
438→						url: context.url,
439→						reason: "LLM returned an empty response.",
440→					});
441→				}
442→
443→				return parseExtractedData(JSON.parse(content), context);
444→			},
445→			catch: (cause) =>
446→				cause instanceof ExtractionError
447→					? cause
448→					: new ExtractionError({
449→							url: context.url,
450→							reason: "LLM extraction failed.",
451→							cause,
452→						}),
453→		});
454→	}
455→}
456→
457→export interface MockPriceExtractorOptions {
458→	handler?: (html: string, context: PriceExtractionContext) => ExtractedPriceData;
459→}
460→
461→export class MockPriceExtractor implements PriceExtractorApi {
462→	constructor(private readonly options: MockPriceExtractorOptions = {}) {}
463→
464→	extract(
465→		html: string,
466→		context: PriceExtractionContext,
467→	): Effect.Effect<ExtractedPriceData, ExtractionError> {
468→		return Effect.try({
469→			try: () =>
470→				this.options.handler?.(html, context) ?? {
471→					productName: `${context.brand} ${context.region} fixture`,
472→					available: true,
473→					localPrice: 100,
474→					currency: context.expectedCurrency,
475→					confidence: "high",
476→				},
477→			catch: (cause) =>
478→				new ExtractionError({
479→					url: context.url,
480→					reason: "Mock extraction failed.",
481→					cause,
482→				}),
483→		});
484→	}
485→}
486→
487→export class FallbackPriceExtractor implements PriceExtractorApi {
488→	constructor(
489→		private readonly primary: PriceExtractorApi,
490→		private readonly fallback: PriceExtractorApi,
491→	) {}
492→
493→	extract(
494→		html: string,
495→		context: PriceExtractionContext,
496→	): Effect.Effect<ExtractedPriceData, ExtractionError> {
497→		return Effect.catchAll(this.primary.extract(html, context), () =>
498→			this.fallback.extract(html, context),
499→		);
500→	}
501→}
502→
503→export const makePriceExtractor = (): PriceExtractorApi => {
504→	const ruleBased = new RuleBasedPriceExtractor();
505→	return Bun.env.OPENROUTER_API_KEY
506→		? new FallbackPriceExtractor(
507→				new OpenRouterPriceExtractor(Bun.env.OPENROUTER_API_KEY),
508→				ruleBased,
509→			)
510→		: ruleBased;
511→};
512→
513→export const PriceExtractorLive = Layer.succeed(PriceExtractor, makePriceExtractor());
514→
515→export const createPriceExtractorLayer = (extractor?: PriceExtractorApi) =>
516→	Layer.succeed(PriceExtractor, extractor ?? makePriceExtractor());
517→

