 1→import { Layer, ManagedRuntime } from "effect";
 2→
 3→import { createInMemoryConvexStore, type InMemoryConvexStore } from "../convex/store";
 4→import { ConvexClient, makeInMemoryConvexClient } from "./lib/convexEffect";
 5→import { BrandDetector, makeBrandDetector } from "./services/BrandDetector";
 6→import { createCurrencyConverterLayer } from "./services/CurrencyConverter";
 7→import { createExchangeRateLayer, makeExchangeRateService } from "./services/ExchangeRateService";
 8→import { createIndexingJobLayer } from "./services/IndexingJobService";
 9→import {
10→	createIndexingDispatcherLayer,
11→	IndexingDispatcherLive,
12→	IndexingWorkerLive,
13→	type IndexingDispatcherApi,
14→} from "./services/IndexingWorker";
15→import { createPageFetcherLayer, type PageFetcherApi } from "./services/PageFetcher";
16→import { createPriceExtractorLayer, type PriceExtractorApi } from "./services/PriceExtractor";
17→import { createPriceLookupLayer } from "./services/PriceLookup";
18→import { createRegionResolverLayer, type RegionResolverApi } from "./services/RegionResolver";
19→import { UrlNormalizerLive } from "./services/UrlNormalizer";
20→
21→export interface AppEnvironmentOptions {
22→	store?: InMemoryConvexStore;
23→	pageFetcher?: PageFetcherApi;
24→	priceExtractor?: PriceExtractorApi;
25→	regionResolver?: RegionResolverApi;
26→	indexingDispatcher?: IndexingDispatcherApi;
27→}
28→
29→export const makeAppLayer = (options: AppEnvironmentOptions = {}) => {
30→	const store = options.store ?? createInMemoryConvexStore();
31→	const convexClient = makeInMemoryConvexClient(store);
32→	const exchangeRates = makeExchangeRateService(convexClient);
33→	const baseLayer = Layer.mergeAll(
34→		UrlNormalizerLive,
35→		Layer.succeed(ConvexClient, convexClient),
36→		Layer.succeed(BrandDetector, makeBrandDetector(convexClient)),
37→		createExchangeRateLayer(convexClient),
38→		createCurrencyConverterLayer(exchangeRates),
39→		createPriceLookupLayer(convexClient),
40→		createIndexingJobLayer(convexClient),
41→		createRegionResolverLayer(options.regionResolver, convexClient),
42→		createPageFetcherLayer(options.pageFetcher),
43→		createPriceExtractorLayer(options.priceExtractor),
44→	);
45→	const workerLayer = Layer.provide(IndexingWorkerLive, baseLayer);
46→	const dispatcherLayer = options.indexingDispatcher
47→		? createIndexingDispatcherLayer(options.indexingDispatcher)
48→		: Layer.provide(IndexingDispatcherLive, workerLayer);
49→
50→	return Layer.mergeAll(baseLayer, workerLayer, dispatcherLayer);
51→};
