 1→import { Context, Effect, Layer } from "effect";
 2→
 3→import { CacheError } from "../domain/errors";
 4→import type { ProductSnapshot } from "../domain/types";
 5→import type { ConvexClientService } from "../lib/convexEffect";
 6→
 7→export const PRICE_FRESHNESS_WINDOW_HOURS = 24;
 8→
 9→export const isFresh = (fetchedAt: string, now: Date = new Date()): boolean => {
10→	const ageMs = now.getTime() - new Date(fetchedAt).getTime();
11→	return ageMs <= PRICE_FRESHNESS_WINDOW_HOURS * 60 * 60 * 1000;
12→};
13→
14→export interface PriceLookupApi {
15→	getByUrl: (normalizedUrl: string) => Effect.Effect<ProductSnapshot | undefined, CacheError>;
16→}
17→
18→export const PriceLookup = Context.GenericTag<PriceLookupApi>("pricehop/PriceLookup");
19→
20→export const makePriceLookup = (convexClient: ConvexClientService): PriceLookupApi => ({
21→	getByUrl: (normalizedUrl) =>
22→		Effect.gen(function* () {
23→			const product = yield* convexClient.findProductByNormalizedUrl(normalizedUrl);
24→			if (!product) {
25→				return undefined;
26→			}
27→
28→			const prices = yield* convexClient.getPricesByProductId(product.id);
29→			if (prices.length === 0) {
30→				return undefined;
31→			}
32→
33→			const fetchedAt = prices
34→				.map((price) => price.fetchedAt)
35→				.sort((left, right) => right.localeCompare(left))[0]!;
36→
37→			return {
38→				productId: product.id,
39→				productUrl: product.normalizedUrl,
40→				brand: product.brand,
41→				productName: product.productName,
42→				prices: prices.map((price) =>
43→					price.status === "unavailable"
44→						? {
45→								region: price.region,
46→								status: "unavailable" as const,
47→							}
48→						: {
49→								region: price.region,
50→								currency: price.currency,
51→								localPrice: price.localPrice,
52→								usdPrice: price.usdPrice,
53→								exchangeRate: price.exchangeRate,
54→								confidence: price.confidence,
55→							},
56→				),
57→				fetchedAt,
58→			};
59→		}),
60→});
61→
62→export const createPriceLookupLayer = (convexClient: ConvexClientService) =>
63→	Layer.succeed(PriceLookup, makePriceLookup(convexClient));
