 9→type RuntimeRunner = {
10→	runPromise: (effect: Effect.Effect<any, any, any>) => Promise<any>;
11→};
12→
13→export const createPricesRouter = (runtime: RuntimeRunner) => {
14→	const router = new Hono();
15→
16→	router.post("/lookup", async (context) => {
17→		const payload = await context.req.json().catch(() => null);
18→		const decoded = Schema.decodeUnknownEither(LookupRequestSchema)(payload);
19→
20→		if (decoded._tag === "Left") {
21→			context.status(400);
22→			return context.json({
23→				error: "InvalidUrlError",
24→				message: "Request body must contain a string url field.",
25→			});
26→		}
27→
28→		return runJsonEffect(context, runtime, priceLookup(decoded.right.url), (body) =>
29→			context.json(body, body.status === "indexing" ? 202 : 200),
30→		);
31→	});
32→
33→	router.get("/status/:jobId", async (context) =>
34→		runJsonEffect(
35→			context,
36→			runtime,
37→			Effect.flatMap(IndexingJobService, (service) =>
38→				service.getStatus(context.req.param("jobId")),
39→			),
40→			(job) =>
41→				job
42→					? context.json(job, 200)
43→					: ((context.status(404),
44→						context.json({
45→							error: "NotFound",
46→							message: "Indexing job was not found.",
47→						})) as Response),
48→		),
49→	);
50→
51→	return router;
52→};
