29→export const makeAppLayer = (options: AppEnvironmentOptions = {}) => {
30→	const store = options.store ?? createInMemoryConvexStore();
31→	const convexClient = makeInMemoryConvexClient(store);
32→	const exchangeRates = makeExchangeRateService(convexClient);
33→	const baseLayer = Layer.mergeAll(
34→		UrlNormalizerLive,
35→		Layer.succeed(ConvexClient, convexClient),
36→		Layer.succeed(BrandDetector, makeBrandDetector(convexClient)),
37→		createExchangeRateLayer(convexClient),
38→		createCurrencyConverterLayer(exchangeRates),
39→		createPriceLookupLayer(convexClient),
40→		createIndexingJobLayer(convexClient),
41→		createRegionResolverLayer(options.regionResolver, convexClient),
42→		createPageFetcherLayer(options.pageFetcher),
43→		createPriceExtractorLayer(options.priceExtractor),
44→	);
45→	const workerLayer = Layer.provide(IndexingWorkerLive, baseLayer);
46→	const dispatcherLayer = options.indexingDispatcher
47→		? createIndexingDispatcherLayer(options.indexingDispatcher)
48→		: Layer.provide(IndexingDispatcherLive, workerLayer);
49→
50→	return Layer.mergeAll(baseLayer, workerLayer, dispatcherLayer);
51→};
