 28→const formatError = (error: unknown): string => {
 29→	if (typeof error === "string") {
 30→		return error;
 31→	}
 32→
 33→	if (error && typeof error === "object" && "cause" in error) {
 34→		return formatError(error.cause);
 35→	}
 36→
 37→	if (error && typeof error === "object" && "reason" in error && typeof error.reason === "string") {
 38→		return error.reason;
 39→	}
 40→
 41→	if (
 42→		error &&
 43→		typeof error === "object" &&
 44→		"message" in error &&
 45→		typeof error.message === "string"
 46→	) {
 47→		return error.message;
 48→	}
 49→
 50→	if (error && typeof error === "object" && "_tag" in error && typeof error._tag === "string") {
 51→		return error._tag;
 52→	}
 53→
 54→	return "Unknown error";
 55→};
 56→
 57→export const makeIndexingWorker = (
 58→	convex: ConvexClientService,
 59→	resolver: RegionResolverApi,
 60→	fetcher: PageFetcherApi,
 61→	extractor: PriceExtractorApi,
 62→	converter: CurrencyConverterApi,
 63→): IndexingWorkerApi => ({
 64→	processJob: (jobId) =>
 65→		Effect.gen(function* () {
 66→			const job = yield* convex.getIndexingJobById(jobId);
 67→			if (
 68→				!job ||
 69→				job.status === "running" ||
 70→				job.status === "complete" ||
 71→				job.status === "failed"
 72→			) {
 73→				return;
 74→			}
 75→
 76→			const product = yield* convex.getProductById(job.productId);
 77→			if (!product) {
 78→				yield* convex.updateIndexingJobStatus(jobId, "failed", {
 79→					error: `Product ${job.productId} was not found.`,
 80→					completedAt: new Date().toISOString(),
 81→				});
 82→
 83→				return yield* Effect.fail(
 84→					new ProductNotFoundError({
 85→						normalizedUrl: job.productId,
 86→					}),
 87→				);
 88→			}
 89→
 90→			yield* convex.updateIndexingJobStatus(jobId, "running");
 91→
 92→			const results = yield* Effect.forEach(
 93→				job.regions,
 94→				(region) =>
 95→					Effect.either(
 96→						Effect.gen(function* () {
 97→							const expectedCurrency = REGION_TO_CURRENCY[region];
 98→							const regionalUrl = yield* resolver.resolve(
 99→								product.normalizedUrl,
100→								product.brand,
101→								region,
102→							);
103→							const page = yield* fetcher.fetchPage(regionalUrl);
104→
105→							if (page.statusCode >= 400) {
106→								return yield* Effect.fail(
107→									new Error(`Regional fetch returned status ${page.statusCode}`),
108→								);
109→							}
110→
111→							const extracted = yield* extractor.extract(page.html, {
112→								url: regionalUrl,
113→								brand: product.brand,
114→								region,
115→								expectedCurrency,
116→							});
117→
118→							if (!extracted.available || extracted.localPrice === undefined) {
119→								yield* convex.upsertPrices(product.id, [
120→									{
121→										region,
122→										status: "unavailable",
123→										confidence: extracted.confidence,
124→										fetchedAt: page.fetchedAt,
125→									},
126→								]);
127→
128→								return {
129→									region,
130→									productName: extracted.productName,
131→									available: false,
132→								};
133→							}
134→
135→							const currency = extracted.currency ?? expectedCurrency;
136→							const converted = yield* converter.toUsd(extracted.localPrice, currency);
137→
138→							yield* convex.upsertPrices(product.id, [
139→								{
140→									region,
141→									currency,
142→									localPrice: extracted.localPrice,
143→									usdPrice: converted.usdPrice,
144→									exchangeRate: converted.exchangeRate,
145→									confidence: extracted.confidence,
146→									fetchedAt: page.fetchedAt,
147→								},
148→							]);
149→
150→							return {
151→								region,
152→								productName: extracted.productName,
153→								available: true,
154→							};
155→						}),
156→					),
157→				{ concurrency: 3 },
158→			).pipe(Effect.ensuring(fetcher.shutdown()));
159→
160→			const successes = results
161→				.filter(
162→					(result): result is Extract<typeof result, { _tag: "Right" }> => result._tag === "Right",
163→				)
164→				.map((result) => result.right);
165→			const failures = results
166→				.filter(
167→					(result): result is Extract<typeof result, { _tag: "Left" }> => result._tag === "Left",
168→				)
169→				.map((result) => formatError(result.left));
170→
171→			const productName = successes.find((result) => result.productName)?.productName;
172→			if (productName) {
173→				yield* convex.updateProductName(product.id, productName);
174→			}
175→
176→			yield* convex.updateIndexingJobStatus(jobId, successes.length > 0 ? "complete" : "failed", {
177→				error: failures.length > 0 ? failures.join("; ") : undefined,
178→				completedAt: new Date().toISOString(),
179→			});
180→
181→			if (successes.length === 0 && failures.length > 0) {
182→				return yield* Effect.fail(new Error(failures.join("; ")));
183→			}
184→		}),
185→});
186→
187→export const IndexingWorkerLive = Layer.effect(
188→	IndexingWorker,
189→	Effect.gen(function* () {
190→		const convex = yield* ConvexClient;
191→		const resolver = yield* RegionResolver;
192→		const fetcher = yield* PageFetcher;
193→		const extractor = yield* PriceExtractor;
194→		const converter = yield* CurrencyConverter;
195→
196→		return makeIndexingWorker(convex, resolver, fetcher, extractor, converter);
197→	}),
198→);
199→
200→export const makeIndexingDispatcher = (worker: IndexingWorkerApi): IndexingDispatcherApi => ({
201→	dispatch: (jobId) =>
202→		Effect.asVoid(Effect.forkDaemon(Effect.catchAll(worker.processJob(jobId), () => Effect.void))),
203→});
204→
205→export const IndexingDispatcherLive = Layer.effect(
206→	IndexingDispatcher,
207→	Effect.map(IndexingWorker, (worker) => makeIndexingDispatcher(worker)),
208→);
209→
210→export const createIndexingDispatcherLayer = (dispatcher: IndexingDispatcherApi) =>
211→	Layer.succeed(IndexingDispatcher, dispatcher);
