 1→import { Effect } from "effect";
 2→import type { Context as HonoContext } from "hono";
 3→import type { StatusCode } from "hono/utils/http-status";
 4→
 5→type RuntimeRunner = {
 6→	runPromise: (effect: Effect.Effect<any, any, any>) => Promise<any>;
 7→};
 8→
 9→const getHttpStatus = (tag: string): StatusCode => {
10→	switch (tag) {
11→		case "InvalidUrlError":
12→		case "UnsupportedBrandError":
13→			return 400;
14→		case "ProductNotFoundError":
15→			return 404;
16→		case "ExchangeRateError":
17→		case "ScrapingError":
18→		case "ExtractionError":
19→			return 502;
20→		case "CacheError":
21→		default:
22→			return 500;
23→	}
24→};
25→
26→export const runJsonEffect = async <A, E extends { _tag: string; message?: string }, R>(
27→	context: HonoContext,
28→	runtime: RuntimeRunner,
29→	effect: Effect.Effect<A, E, R>,
30→	onSuccess: (value: A) => Response | Promise<Response>,
31→): Promise<Response> => {
32→	const outcome = await runtime.runPromise(Effect.either(effect));
33→
34→	if (outcome._tag === "Left") {
35→		context.status(getHttpStatus(outcome.left._tag));
36→		return context.json({
37→			error: outcome.left._tag,
38→			message: outcome.left.message ?? outcome.left._tag,
39→		});
40→	}
41→
42→	return onSuccess(outcome.right);
43→};
