 1→const STRIP_BLOCK_TAGS = ["script", "style", "svg", "noscript"];
 2→const STRIP_SELF_CLOSING_TAGS = ["img"];
 3→const DEFAULT_MAX_BYTES = 50_000;
 4→
 5→const truncateByBytes = (value: string, maxBytes: number): string => {
 6→	const encoder = new TextEncoder();
 7→	if (encoder.encode(value).length <= maxBytes) {
 8→		return value;
 9→	}
10→
11→	let low = 0;
12→	let high = value.length;
13→
14→	while (low < high) {
15→		const mid = Math.ceil((low + high) / 2);
16→		const candidate = value.slice(0, mid);
17→		if (encoder.encode(candidate).length <= maxBytes) {
18→			low = mid;
19→		} else {
20→			high = mid - 1;
21→		}
22→	}
23→
24→	return value.slice(0, low);
25→};
26→
27→export interface CleanHtmlOptions {
28→	maxBytes?: number;
29→}
30→
31→export const cleanHtml = (html: string, options: CleanHtmlOptions = {}): string => {
32→	const maxBytes = options.maxBytes ?? DEFAULT_MAX_BYTES;
33→	let cleaned = html.replace(/<!--[\s\S]*?-->/gu, " ");
34→
35→	for (const tag of STRIP_BLOCK_TAGS) {
36→		cleaned = cleaned.replace(new RegExp(`<${tag}\\b[\\s\\S]*?<\\/${tag}>`, "giu"), " ");
37→	}
38→
39→	for (const tag of STRIP_SELF_CLOSING_TAGS) {
40→		cleaned = cleaned.replace(new RegExp(`<${tag}\\b[^>]*>`, "giu"), " ");
41→	}
42→
43→	cleaned = cleaned.replace(/>\s+</gu, "><").replace(/\s+/gu, " ").trim();
44→
45→	return truncateByBytes(cleaned, maxBytes);
46→};
