 1→import { Context, Effect, Layer } from "effect";
 2→
 3→import type { Brand } from "../domain/brands";
 4→import { CacheError, ScrapingError } from "../domain/errors";
 5→import type { Region } from "../domain/regions";
 6→import type { ConvexClientService } from "../lib/convexEffect";
 7→
 8→export interface RegionResolverApi {
 9→	resolve: (
10→		productUrl: string,
11→		brand: Brand,
12→		region: Region,
13→	) => Effect.Effect<string, ScrapingError | CacheError>;
14→}
15→
16→export const RegionResolver = Context.GenericTag<RegionResolverApi>("pricehop/RegionResolver");
17→
18→const LOCALE_PREFIX_PATTERN = /^\/[a-z]{2}-[a-z]{2}(?=\/|$)/iu;
19→
20→const stripLocalePrefix = (pathname: string): string =>
21→	pathname.replace(LOCALE_PREFIX_PATTERN, "") || "/";
22→
23→const joinPath = (...parts: string[]): string => {
24→	const normalized = parts
25→		.filter((part) => part.length > 0)
26→		.map((part) => part.replace(/^\/+/u, "").replace(/\/+$/u, ""))
27→		.filter((part) => part.length > 0);
28→
29→	return normalized.length === 0 ? "/" : `/${normalized.join("/")}`;
30→};
31→
32→export const makeRegionResolver = (convexClient: ConvexClientService): RegionResolverApi => ({
33→	resolve: (productUrl, brand, region) =>
34→		Effect.gen(function* () {
35→			const brandRecord = yield* convexClient.getBrandByName(brand);
36→			if (!brandRecord) {
37→				return yield* Effect.fail(
38→					new ScrapingError({
39→						url: productUrl,
40→						cause: `No brand mapping for ${brand}`,
41→					}),
42→				);
43→			}
44→
45→			const entry = yield* convexClient.getBrandUrlByBrandIdAndRegion(brandRecord.id, region);
46→			if (!entry) {
47→				return yield* Effect.fail(
48→					new ScrapingError({
49→						url: productUrl,
50→						cause: `No regional site mapping for ${brand} ${region}`,
51→					}),
52→				);
53→			}
54→
55→			return yield* Effect.try({
56→				try: () => {
57→					const sourceUrl = new URL(productUrl);
58→					const targetUrl = new URL(entry.baseUrl);
59→					const sourcePath = sourceUrl.pathname || "/";
60→
61→					targetUrl.pathname =
62→						entry.urlTransform === "locale-prefix"
63→							? joinPath(
64→									targetUrl.pathname,
65→									entry.localePrefix ?? "",
66→									stripLocalePrefix(sourcePath),
67→								)
68→							: joinPath(targetUrl.pathname, sourcePath);
69→					targetUrl.search = "";
70→					targetUrl.hash = "";
71→
72→					return targetUrl.toString();
73→				},
74→				catch: (cause) =>
75→					new ScrapingError({
76→						url: productUrl,
77→						cause,
78→					}),
79→			});
80→		}),
81→});
82→
83→export const createRegionResolverLayer = (
84→	resolver: RegionResolverApi | undefined,
85→	convexClient: ConvexClientService,
86→) => Layer.succeed(RegionResolver, resolver ?? makeRegionResolver(convexClient));
