  1→import { Context, Effect, Layer } from "effect";
  2→import OpenAI from "openai";
  3→
  4→import { ExtractionError } from "../domain/errors";
  5→import type { CurrencyCode, Region } from "../domain/regions";
  6→import type { ExtractedPriceData } from "../domain/types";
  7→import { cleanHtml } from "../lib/htmlCleaner";
  8→
  9→export interface PriceExtractionContext {
 10→	url: string;
 11→	brand: string;
 12→	region: Region;
 13→	expectedCurrency: CurrencyCode;
 14→}
 15→
 16→export interface PriceExtractorApi {
 17→	extract: (
 18→		html: string,
 19→		context: PriceExtractionContext,
 20→	) => Effect.Effect<ExtractedPriceData, ExtractionError>;
 21→}
 22→
 23→export const PriceExtractor = Context.GenericTag<PriceExtractorApi>("pricehop/PriceExtractor");
 24→
 25→const normalizeWhitespace = (value: string | null | undefined): string | undefined => {
 26→	const normalized = value?.replace(/\s+/gu, " ").trim();
 27→	return normalized ? normalized : undefined;
 28→};
 29→
 30→const normalizeProductName = (value: string | null | undefined): string | undefined => {
 31→	const normalized = normalizeWhitespace(value);
 32→	if (!normalized) {
 33→		return undefined;
 34→	}
 35→
 36→	return normalized.replace(/\s+\|\s+.*$/u, "").replace(/\s+-\s+.*$/u, "");
 37→};
 38→
 39→const parsePriceNumber = (value: string | number | undefined): number | undefined => {
 40→	if (typeof value === "number") {
 41→		return Number.isFinite(value) ? value : undefined;
 42→	}
 43→
 44→	if (!value) {
 45→		return undefined;
 46→	}
 47→
 48→	const normalized = value.replace(/[^\d.,-]/gu, "").trim();
 49→	if (!normalized) {
 50→		return undefined;
 51→	}
 52→
 53→	const hasComma = normalized.includes(",");
 54→	const hasDot = normalized.includes(".");
 55→	let candidate = normalized;
 56→
 57→	if (hasComma && hasDot) {
 58→		candidate = normalized.replace(/,/gu, "");
 59→	} else if (hasComma && !hasDot) {
 60→		candidate = normalized.replace(/,/gu, ".");
 61→	}
 62→
 63→	const parsed = Number(candidate);
 64→	return Number.isFinite(parsed) ? parsed : undefined;
 65→};
 66→
 67→const isRecord = (value: unknown): value is Record<string, unknown> =>
 68→	typeof value === "object" && value !== null && !Array.isArray(value);
 69→
 70→const asArray = (value: unknown): unknown[] => (Array.isArray(value) ? value : [value]);
 71→
 72→const findOfferRecord = (value: unknown): Record<string, unknown> | undefined => {
 73→	if (Array.isArray(value)) {
 74→		for (const item of value) {
 75→			const record = findOfferRecord(item);
 76→			if (record) {
 77→				return record;
 78→			}
 79→		}
 80→		return undefined;
 81→	}
 82→
 83→	if (!isRecord(value)) {
 84→		return undefined;
 85→	}
 86→
 87→	if (isRecord(value.offers)) {
 88→		return value.offers;
 89→	}
 90→
 91→	if (Array.isArray(value.offers)) {
 92→		return value.offers.find(isRecord);
 93→	}
 94→
 95→	if (Array.isArray(value["@graph"])) {
 96→		for (const item of value["@graph"]) {
 97→			const record = findOfferRecord(item);
 98→			if (record) {
 99→				return record;
100→			}
101→		}
102→	}
103→
104→	return undefined;
105→};
106→
107→const decodeHtmlEntities = (value: string): string =>
108→	value
109→		.replace(/&amp;/gu, "&")
110→		.replace(/&quot;/gu, '"')
111→		.replace(/&#39;/gu, "'")
112→		.replace(/&lt;/gu, "<")
113→		.replace(/&gt;/gu, ">");
114→
115→const stripTags = (value: string): string => decodeHtmlEntities(value.replace(/<[^>]+>/gu, " "));
116→
117→const getTagText = (html: string, tagName: string): string | undefined => {
118→	const match = html.match(new RegExp(`<${tagName}\\b[^>]*>([\\s\\S]*?)<\\/${tagName}>`, "iu"));
119→	return normalizeWhitespace(match?.[1] ? stripTags(match[1]) : undefined);
120→};
121→
122→const getMetaContent = (
123→	html: string,
124→	attribute: "name" | "property",
125→	value: string,
126→): string | undefined => {
127→	const tags = html.match(/<meta\b[^>]*>/giu) ?? [];
128→	const attributePattern = new RegExp(
129→		`${attribute}\\s*=\\s*["']${value.replace(/[.*+?^${}()|[\]\\]/gu, "\\$&")}["']`,
130→		"iu",
131→	);
132→
133→	for (const tag of tags) {
134→		if (!attributePattern.test(tag)) {
135→			continue;
136→		}
137→
138→		const contentMatch = tag.match(/content\s*=\s*["']([^"']+)["']/iu);
139→		if (contentMatch?.[1]) {
140→			return normalizeWhitespace(decodeHtmlEntities(contentMatch[1]));
141→		}
142→	}
143→
144→	return undefined;
145→};
146→
147→const getJsonLdCandidates = (html: string): Record<string, unknown>[] => {
148→	const scripts = [
149→		...html.matchAll(
150→			/<script\b[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/giu,
151→		),
152→	];
153→	const candidates: Record<string, unknown>[] = [];
154→
155→	for (const script of scripts) {
156→		const content = script[1]?.trim();
157→		if (!content) {
158→			continue;
159→		}
160→
161→		try {
162→			const parsed = JSON.parse(content);
163→			for (const item of asArray(parsed)) {
164→				if (isRecord(item)) {
165→					candidates.push(item);
166→				}
167→			}
168→		} catch {
169→			continue;
170→		}
171→	}
172→
173→	return candidates;
174→};
175→
176→const extractStructuredData = (
177→	html: string,
178→	expectedCurrency: CurrencyCode,
179→): ExtractedPriceData | undefined => {
180→	const jsonLd = getJsonLdCandidates(html);
181→
182→	for (const entry of jsonLd) {
183→		const offer = findOfferRecord(entry);
184→		const productName = normalizeProductName(
185→			typeof entry.name === "string" ? entry.name : undefined,
186→		);
187→		const sku = normalizeWhitespace(typeof entry.sku === "string" ? entry.sku : undefined);
188→		const currency = normalizeWhitespace(
189→			typeof offer?.priceCurrency === "string" ? offer.priceCurrency : undefined,
190→		) as CurrencyCode | undefined;
191→		const localPrice = parsePriceNumber(
192→			typeof offer?.price === "string" || typeof offer?.price === "number"
193→				? offer.price
194→				: undefined,
195→		);
196→		const availability = normalizeWhitespace(
197→			typeof offer?.availability === "string" ? offer.availability : undefined,
198→		);
199→
200→		if (productName || localPrice !== undefined || availability) {
201→			const available =
202→				availability?.toLowerCase().includes("outofstock") ||
203→				availability?.toLowerCase().includes("soldout")
204→					? false
205→					: localPrice !== undefined;
206→
207→			return {
208→				productName,
209→				sku,
210→				localPrice,
211→				currency: currency ?? expectedCurrency,
212→				available,
213→				confidence: currency === expectedCurrency || currency === undefined ? "high" : "medium",
214→			};
215→		}
216→	}
217→
218→	return undefined;
219→};
220→
221→const extractMetaData = (
222→	html: string,
223→	expectedCurrency: CurrencyCode,
224→): ExtractedPriceData | undefined => {
225→	const productName = normalizeProductName(
226→		getMetaContent(html, "property", "og:title") ??
227→			getMetaContent(html, "name", "twitter:title") ??
228→			getTagText(html, "h1") ??
229→			getTagText(html, "title"),
230→	);
231→	const sku = normalizeWhitespace(
232→		getMetaContent(html, "name", "sku") ??
233→			getMetaContent(html, "property", "product:retailer_item_id"),
234→	);
235→	const localPrice = parsePriceNumber(
236→		getMetaContent(html, "property", "product:price:amount") ??
237→			getMetaContent(html, "name", "price"),
238→	);
239→	const currency = normalizeWhitespace(
240→		getMetaContent(html, "property", "product:price:currency") ??
241→			getMetaContent(html, "name", "currency"),
242→	) as CurrencyCode | undefined;
243→
244→	if (!productName && localPrice === undefined) {
245→		return undefined;
246→	}
247→
248→	return {
249→		productName,
250→		sku,
251→		localPrice,
252→		currency: currency ?? expectedCurrency,
253→		available: localPrice !== undefined,
254→		confidence: currency === expectedCurrency || currency === undefined ? "high" : "medium",
255→	};
256→};
257→
258→const CURRENCY_SYMBOLS: Record<CurrencyCode, string[]> = {
259→	AUD: ["A$", "$"],
260→	CAD: ["C$", "$"],
261→	CNY: ["CN¥", "¥"],
262→	HKD: ["HK$", "$"],
263→	KRW: ["₩", "KRW"],
264→	PHP: ["₱", "PHP"],
265→	SGD: ["S$", "$"],
266→	THB: ["฿", "THB"],
267→	TWD: ["NT$", "TWD"],
268→	USD: ["US$", "$"],
269→};
270→
271→const extractVisiblePrice = (
272→	html: string,
273→	expectedCurrency: CurrencyCode,
274→): ExtractedPriceData | undefined => {
275→	const pricePatterns = CURRENCY_SYMBOLS[expectedCurrency]
276→		.map((symbol) => symbol.replace(/[.*+?^${}()|[\]\\]/gu, "\\$&"))
277→		.map((escaped) => new RegExp(`${escaped}\\s*([\\d,.]+)`, "u"));
278→
279→	for (const pattern of pricePatterns) {
280→		const match = html.match(pattern);
281→		if (!match?.[1]) {
282→			continue;
283→		}
284→
285→		const localPrice = parsePriceNumber(match[1]);
286→		if (localPrice === undefined) {
287→			continue;
288→		}
289→
290→		return {
291→			productName: normalizeProductName(getTagText(html, "h1") ?? getTagText(html, "title")),
292→			sku:
293→				normalizeWhitespace(
294→					html.match(/(?:sku|style|item)\s*(?:#|number|no\.?)?\s*[:#]?\s*([a-z0-9-]+)/iu)?.[1],
295→				) ?? undefined,
296→			localPrice,
297→			currency: expectedCurrency,
298→			available: true,
299→			confidence: "medium",
300→		};
301→	}
302→
303→	if (/(sold out|out of stock|unavailable)/iu.test(html)) {
304→		return {
305→			productName: normalizeProductName(getTagText(html, "h1") ?? getTagText(html, "title")),
306→			available: false,
307→			confidence: "low",
308→		};
309→	}
310→
311→	return undefined;
312→};
313→
314→const parseExtractedData = (
315→	value: unknown,
316→	context: PriceExtractionContext,
317→): ExtractedPriceData => {
318→	if (!isRecord(value) || typeof value.available !== "boolean") {
319→		throw new ExtractionError({
320→			url: context.url,
321→			reason: "Structured model response was not a valid extraction payload.",
322→			cause: value,
323→		});
324→	}
325→
326→	const confidence =
327→		value.confidence === "high" || value.confidence === "medium" || value.confidence === "low"
328→			? value.confidence
329→			: "low";
330→
331→	return {
332→		productName: normalizeProductName(
333→			typeof value.productName === "string" ? value.productName : undefined,
334→		),
335→		sku: normalizeWhitespace(typeof value.sku === "string" ? value.sku : undefined),
336→		localPrice: parsePriceNumber(
337→			typeof value.localPrice === "string" || typeof value.localPrice === "number"
338→				? value.localPrice
339→				: undefined,
340→		),
341→		currency: normalizeWhitespace(
342→			typeof value.currency === "string" ? value.currency : undefined,
343→		) as CurrencyCode | undefined,
344→		available: value.available,
345→		confidence:
346→			(value.currency === context.expectedCurrency || value.currency === undefined) &&
347→			confidence === "low"
348→				? "medium"
349→				: confidence,
350→	};
351→};
352→
353→export class RuleBasedPriceExtractor implements PriceExtractorApi {
354→	extract(
355→		html: string,
356→		context: PriceExtractionContext,
357→	): Effect.Effect<ExtractedPriceData, ExtractionError> {
358→		return Effect.try({
359→			try: () => {
360→				const structured = extractStructuredData(html, context.expectedCurrency);
361→				const meta = structured ?? extractMetaData(html, context.expectedCurrency);
362→				const visible = meta ?? extractVisiblePrice(html, context.expectedCurrency);
363→
364→				if (!visible) {
365→					throw new ExtractionError({
366→						url: context.url,
367→						reason: "Could not extract product data from page HTML.",
368→					});
369→				}
370→
371→				return visible;
372→			},
373→			catch: (cause) =>
374→				cause instanceof ExtractionError
375→					? cause
376→					: new ExtractionError({
377→							url: context.url,
378→							reason: "Rule-based extraction failed.",
379→							cause,
380→						}),
381→		});
382→	}
383→}
