443→				return parseExtractedData(JSON.parse(content), context);
444→			},
445→			catch: (cause) =>
446→				cause instanceof ExtractionError
447→					? cause
448→					: new ExtractionError({
449→							url: context.url,
450→							reason: "LLM extraction failed.",
451→							cause,
