 54→interface BrightDataResponseEnvelope {
 55→	status_code?: number;
 56→	body?: string;
 57→}
 58→
 59→interface BrightDataRequestBody {
 60→	zone: string;
 61→	url: string;
 62→	format: "raw";
 63→	headers?: Record<string, string>;
 64→}
 65→
 66→const makeBrightDataRequestBody = (
 67→	zone: string,
 68→	url: string,
 69→	options?: FetchPageOptions,
 70→): BrightDataRequestBody => {
 71→	const headers = options?.waitSelector
 72→		? {
 73→				"x-unblock-expect": JSON.stringify({
 74→					element: options.waitSelector,
 75→				}),
 76→			}
 77→		: undefined;
 78→
 79→	return {
 80→		zone,
 81→		url,
 82→		format: "raw",
 83→		...(headers ? { headers } : {}),
 84→	};
 85→};
 86→
 87→const readBrightDataResponse = async (
 88→	response: Response,
 89→): Promise<Pick<RawPageResult, "html" | "statusCode">> => {
 90→	if (!response.ok) {
 91→		throw new Error(`Bright Data request failed with status ${response.status}.`);
 92→	}
 93→
 94→	const contentType = response.headers.get("content-type") ?? "";
 95→
 96→	if (contentType.includes("application/json")) {
 97→		const payload = (await response.json()) as BrightDataResponseEnvelope;
 98→		if (!payload.body) {
 99→			throw new Error("Bright Data returned no HTML content.");
100→		}
101→
102→		return {
103→			html: payload.body,
104→			statusCode: payload.status_code ?? response.status,
105→		};
106→	}
107→
108→	const html = await response.text();
109→	if (!html) {
110→		throw new Error("Bright Data returned no HTML content.");
111→	}
112→
113→	return {
114→		html,
115→		statusCode: response.status,
116→	};
117→};
