119→export class BrightDataPageFetcher implements PageFetcherApi {
120→	constructor(
121→		private readonly apiKey: string,
122→		private readonly zone: string,
123→		private readonly fetchImpl: typeof fetch = fetch,
124→	) {}
125→
126→	fetchPage(url: string, options?: FetchPageOptions): Effect.Effect<RawPageResult, ScrapingError> {
127→		return Effect.tryPromise({
128→			try: async () => {
129→				const response = await this.fetchImpl("https://api.brightdata.com/request", {
130→					method: "POST",
131→					headers: {
132→						Authorization: `Bearer ${this.apiKey}`,
133→						"Content-Type": "application/json",
134→					},
135→					body: JSON.stringify(makeBrightDataRequestBody(this.zone, url, options)),
136→				});
137→				const page = await readBrightDataResponse(response);
138→
139→				return {
140→					url,
141→					html: page.html,
142→					statusCode: page.statusCode,
143→					fetchedAt: new Date().toISOString(),
144→				};
145→			},
146→			catch: (cause) => toScrapingError(url, cause),
147→		});
148→	}
149→
150→	shutdown(): Effect.Effect<void> {
151→		return Effect.void;
152→	}
153→}
