169→	fetchPage(url: string): Effect.Effect<RawPageResult, ScrapingError> {
170→		return Effect.try({
171→			try: () => {
172→				const value = this.options.fixtures?.[url] ?? this.options.fallback?.(url);
173→				if (!value) {
174→					throw new Error(`No fixture configured for ${url}`);
175→				}
176→
177→				const fixture = typeof value === "string" ? { html: value } : value;
178→				return {
179→					url,
180→					html: fixture.html,
181→					statusCode: fixture.statusCode ?? 200,
182→					fetchedAt: new Date().toISOString(),
183→				};
184→			},
185→			catch: (cause) => toScrapingError(url, cause),
186→		});
187→	}
188→
189→	shutdown(): Effect.Effect<void> {
190→		return Effect.sync(() => {
191→			this.options.onShutdown?.();
192→		});
193→	}
194→}
