 38→	if (error && typeof error === "object" && "cause" in error) {
 39→		return formatError(error.cause);
 40→	}
 41→
 42→	if (error && typeof error === "object" && "reason" in error && typeof error.reason === "string") {
 43→		return error.reason;
 44→	}
 45→
 46→	if (
 47→		error &&
 48→		typeof error === "object" &&
 49→		"message" in error &&
 50→		typeof error.message === "string"
 51→	) {
 52→		return error.message;
 53→	}
 54→
 55→	if (error && typeof error === "object" && "_tag" in error && typeof error._tag === "string") {
 56→		return error._tag;
 57→	}
 58→
 59→	return "Unknown error";
 60→};
 61→
