 63→	(SUPPORTED_CURRENCIES as readonly string[]).includes(code);
 64→
 65→const skusOverlap = (a: string, b: string): boolean => {
 66→	const setA = new Set(a.split(/[,\s]+/u).map((s) => s.trim()).filter(Boolean));
 67→	const setB = new Set(b.split(/[,\s]+/u).map((s) => s.trim()).filter(Boolean));
 68→	for (const sku of setA) {
 69→		if (setB.has(sku)) return true;
 70→	}
