 94→					error: `Product ${job.productId} was not found.`,
 95→					completedAt: new Date().toISOString(),
 96→				});
 97→
 98→				return yield* Effect.fail(
 99→					new ProductNotFoundError({
100→						normalizedUrl: job.productId,
101→					}),
102→				);
103→			}
104→
105→			yield* convex.updateIndexingJobStatus(jobId, "running");
106→
107→			yield* Effect.catchAll(
108→				Effect.gen(function* () {
109→					// Step 4: Extract source product
