128→						sourceRegion,
129→						job.regions,
130→					);
131→
132→					// Step 8: Determine target regions
133→					const targetRegions = job.regions.filter(
134→						(region) => region !== sourceRegion,
135→					);
136→
137→					// Step 9: Process each target region
138→					const brandRecord = yield* convex.getBrandByName(product.brand);
139→
140→					const targetResults = yield* Effect.forEach(
141→						targetRegions,
142→						(region) =>
143→							Effect.either(
144→								processTargetRegion(
145→									convex,
146→									scrapingBee,
147→									converter,
148→									product.id,
149→									sourceData,
150→									region,
151→									brandRecord?.id,
152→								),
153→							),
154→						{ concurrency: 3 },
155→					);
156→
157→					// Step 10-11: Tally results
158→					const allResults = [
159→						...(sourceResult ? [sourceResult] : []),
160→						...targetResults,
161→					];
162→
163→					const successes = allResults.filter(
164→						(r): r is Extract<typeof r, { _tag: "Right" }> =>
165→							r._tag === "Right",
166→					);
167→					const failures = allResults
168→						.filter(
169→							(r): r is Extract<typeof r, { _tag: "Left" }> =>
170→								r._tag === "Left",
171→						)
172→						.map((r) => formatError(r.left));
173→
174→					yield* convex.updateIndexingJobStatus(
175→						jobId,
176→						successes.length > 0 ? "complete" : "failed",
177→						{
178→							error:
179→								failures.length > 0
180→									? failures.join("; ")
181→									: undefined,
182→							completedAt: new Date().toISOString(),
183→						},
184→					);
185→
186→					if (successes.length === 0 && failures.length > 0) {
187→						return yield* Effect.fail(new Error(failures.join("; ")));
