201→const processSourceRegion = (
202→	convex: ConvexClientService,
203→	converter: CurrencyConverterApi,
204→	productId: string,
205→	sourceData: ScrapingBeeExtractedData,
206→	sourceRegion: Region | undefined,
207→	jobRegions: readonly Region[],
208→) => {
209→	if (!sourceRegion || !jobRegions.includes(sourceRegion)) {
210→		return Effect.succeed(undefined);
211→	}
212→
213→	return Effect.either(
214→		Effect.gen(function* () {
215→			const expectedCurrency = REGION_TO_CURRENCY[sourceRegion];
216→
217→			if (!sourceData.available) {
218→				yield* convex.upsertPrices(productId, [
219→					{
220→						region: sourceRegion,
221→						status: "unavailable",
222→						confidence: "high",
223→						fetchedAt: new Date().toISOString(),
224→					},
225→				]);
