233→				);
234→			}
235→
236→			let currency: CurrencyCode;
237→			let confidence: "high" | "medium" | "low";
238→
239→			if (sourceData.currency && isSupportedCurrency(sourceData.currency)) {
240→				currency = sourceData.currency;
241→				confidence = currency === expectedCurrency ? "high" : "medium";
242→			} else if (sourceData.currency) {
243→				return yield* Effect.fail(
244→					new Error(`Unsupported source currency: ${sourceData.currency}`),
245→				);
246→			} else {
247→				currency = expectedCurrency;
248→				confidence = "high";
249→			}
250→
251→			const converted = yield* converter.toUsd(localPrice, currency);
252→
253→			yield* convex.upsertPrices(productId, [
254→				{
255→					region: sourceRegion,
256→					currency,
257→					localPrice,
258→					usdPrice: converted.usdPrice,
259→					exchangeRate: converted.exchangeRate,
260→					confidence,
261→					fetchedAt: new Date().toISOString(),
262→				},
263→			]);
264→
265→			return { region: sourceRegion, available: true };
266→		}),
267→	);
268→};
269→
270→const processTargetRegion = (
271→	convex: ConvexClientService,
272→	scrapingBee: ScrapingBeeServiceApi,
273→	converter: CurrencyConverterApi,
274→	productId: string,
275→	sourceData: ScrapingBeeExtractedData,
276→	region: Region,
277→	brandId: string | undefined,
278→) =>
279→	Effect.gen(function* () {
280→		// Step 9a: Look up allowed hostname
281→		if (!brandId) {
282→			return yield* Effect.fail(new Error(`No brand record found`));
283→		}
284→
285→		const brandUrl = yield* convex.getBrandUrlByBrandIdAndRegion(brandId, region);
286→		if (!brandUrl) {
287→			return yield* Effect.fail(
288→				new Error(`No brand_urls entry for region ${region}`),
289→			);
290→		}
291→
292→		const expectedHostname = new URL(brandUrl.baseUrl).hostname;
293→
294→		// Step 9b: Build search query
295→		const skusPart = sourceData.skus ? ` ${sourceData.skus}` : "";
296→		const countryName = REGION_TO_COUNTRY_NAME[region];
297→		const query = `${sourceData.name}${skusPart} ${countryName} price`;
298→
299→		// Step 9c: Search
300→		const foundUrl = yield* scrapingBee.searchProduct(
301→			query,
302→			REGION_TO_COUNTRY_CODE[region],
303→		);
304→
305→		// Step 9d: Empty results
306→		if (foundUrl === null) {
307→			return yield* Effect.fail(
308→				new Error(`No search results for ${region}`),
309→			);
310→		}
311→
312→		// Step 9e: Validate hostname
313→		const foundHostname = new URL(foundUrl).hostname;
314→		if (foundHostname !== expectedHostname) {
315→			return yield* Effect.fail(
316→				new Error(
317→					`Hostname mismatch for ${region}: expected ${expectedHostname}, got ${foundHostname}`,
318→				),
319→			);
320→		}
321→
322→		// Step 9f: Extract from found URL
323→		const extracted = yield* scrapingBee.extractProduct(foundUrl);
324→
325→		// Validate country
326→		const extractedRegion =
327→			COUNTRY_CODE_TO_REGION[extracted.countryCode.toUpperCase()];
328→		if (extractedRegion !== region) {
329→			return yield* Effect.fail(
330→				new Error(
331→					`Country mismatch for ${region}: extracted ${extracted.countryCode}`,
332→				),
333→			);
334→		}
335→
336→		// Validate product identity via SKU overlap
337→		let skuVerified = false;
338→		if (sourceData.skus && extracted.skus) {
339→			if (!skusOverlap(sourceData.skus, extracted.skus)) {
340→				return yield* Effect.fail(
341→					new Error(`SKU mismatch for ${region}: wrong product`),
342→				);
343→			}
344→			skuVerified = true;
345→		}
346→
347→		const expectedCurrency = REGION_TO_CURRENCY[region];
348→
349→		// Unavailable
350→		if (!extracted.available) {
351→			yield* convex.upsertPrices(productId, [
352→				{
353→					region,
354→					status: "unavailable",
355→					confidence: "medium",
356→					fetchedAt: new Date().toISOString(),
357→				},
358→			]);
359→			return { region, available: false };
360→		}
361→
362→		// Parse price
363→		const localPrice = parsePriceNumber(extracted.price);
364→		if (localPrice === undefined) {
365→			return yield* Effect.fail(
366→				new Error(`Price unparseable for ${region}`),
367→			);
368→		}
369→
370→		// Currency resolution
371→		let currency: CurrencyCode;
372→		let currencyMatches = true;
373→
374→		if (extracted.currency && isSupportedCurrency(extracted.currency)) {
375→			currency = extracted.currency;
376→			currencyMatches = currency === expectedCurrency;
377→		} else if (extracted.currency) {
378→			return yield* Effect.fail(
379→				new Error(`Unsupported currency for ${region}: ${extracted.currency}`),
380→			);
381→		} else {
382→			currency = expectedCurrency;
383→		}
384→
385→		// Confidence
386→		let confidence: "high" | "medium" | "low" = "medium";
387→		if (!currencyMatches || !skuVerified) {
388→			confidence = "low";
389→		}
390→
391→		const converted = yield* converter.toUsd(localPrice, currency);
392→
393→		yield* convex.upsertPrices(productId, [
394→			{
395→				region,
396→				currency,
397→				localPrice,
398→				usdPrice: converted.usdPrice,
399→				exchangeRate: converted.exchangeRate,
400→				confidence,
401→				fetchedAt: new Date().toISOString(),
402→			},
403→		]);
404→
405→		return { region, available: true };
406→	});
407→
408→export const IndexingWorkerLive = Layer.effect(
409→	IndexingWorker,
410→	Effect.gen(function* () {
411→		const convex = yield* ConvexClient;
412→		const scrapingBee = yield* ScrapingBeeService;
413→		const converter = yield* CurrencyConverter;
414→
415→		return makeIndexingWorker(convex, scrapingBee, converter);
416→	}),
417→);
418→
419→export const makeIndexingDispatcher = (worker: IndexingWorkerApi): IndexingDispatcherApi => ({
420→	dispatch: (jobId) =>
421→		Effect.asVoid(Effect.forkDaemon(Effect.catchAll(worker.processJob(jobId), () => Effect.void))),
422→});
423→
424→export const IndexingDispatcherLive = Layer.effect(
425→	IndexingDispatcher,
426→	Effect.map(IndexingWorker, (worker) => makeIndexingDispatcher(worker)),
427→);
428→
429→export const createIndexingDispatcherLayer = (dispatcher: IndexingDispatcherApi) =>
430→	Layer.succeed(IndexingDispatcher, dispatcher);
